method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires |extensions| > 0 // There must be at least one extension
    requires class_name != "" // The class name must not be an empty string
    ensures result == class_name + "." + strongestExtension // The result is in the correct format
    ensures strongestExtension in extensions // The strongest extension is one of the provided extensions
    ensures forall ext: string :: ext in extensions ==> (strength(ext) <= strength(strongestExtension) ==> ext == strongestExtension) // The chosen extension has the highest strength
{
    var strongestExtension: string := extensions[0];
    var maxStrength: int := strength(strongestExtension);

    var i: int := 1;
    while i < |extensions|
        invariant 0 <= i <= |extensions| // i is within bounds of the extensions sequence
        invariant maxStrength == strength(strongestExtension) // maxStrength holds the strength of the current strongest extension
        invariant strongestExtension in extensions // The strongest extension is in the list of extensions
    {
        var currentExtension: string := extensions[i];
        var currentStrength: int := strength(currentExtension);

        if currentStrength > maxStrength {
            strongestExtension := currentExtension;
            maxStrength := currentStrength;
        }

        i := i + 1;
    }

    result := class_name + "." + strongestExtension;
}

method strength(extension: string) returns (s: int)
    ensures s == (CAP(extension) - SM(extension)) // The strength is defined as the difference between uppercase and lowercase letters
{
    var cap: int := 0;
    var sm: int := 0;

    var i: int := 0;
    while i < |extension|
        invariant 0 <= i <= |extension| // i is within bounds of the extension string
        invariant cap + sm == countLetters(extension, i) // Total letters counted so far
    {
        if extension[i] >= 'A' && extension[i] <= 'Z' {
            cap := cap + 1;
        } else if extension[i] >= 'a' && extension[i] <= 'z' {
            sm := sm + 1;
        }

        i := i + 1;
    }

    s := cap - sm;
}

method countLetters(s: string, upto: int) returns (count: int)
    ensures count == |s[0..upto]| // Count of letters up to the specified index
{
    count := upto; // Simply return the number of characters counted
}
